#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'build/PrePoMax-CodeAster')
path = root / 'PrePoMax' / 'AsterMaxAI' / 'AsterMaxStepMeshHarness.cs'
text = path.read_text(encoding='utf-8-sig')

entry_anchor = '''            string evidencePath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_EVIDENCE_PATH");\n            string stepPath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_PATH");'''
entry_replacement = '''            string evidencePath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_EVIDENCE_PATH");\n            string stepPath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_PATH");\n            string c882MaxHText = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_MAXH_MM");\n            string c882CfgPath = Environment.GetEnvironmentVariable("ASTERMAX_STEP_MESH_CONFIG_EVIDENCE_PATH");\n            if (!String.IsNullOrWhiteSpace(c882CfgPath))\n            {\n                string c882CfgDir = Path.GetDirectoryName(c882CfgPath);\n                if (!String.IsNullOrWhiteSpace(c882CfgDir)) Directory.CreateDirectory(c882CfgDir);\n                File.WriteAllText(c882CfgPath, "{\\n  \\\"schema\\\": \\\"astermax.c8.82.native-netgen-size.v8\\\",\\n" +\n                    "  \\\"request_environment_seen\\\": true,\\n" +\n                    "  \\\"requested_maxh_raw\\\": " + Json(c882MaxHText) + ",\\n" +\n                    "  \\\"part_specific_parameters_admitted\\\": false,\\n" +\n                    "  \\\"native_create_mesh_started\\\": false,\\n" +\n                    "  \\\"meshing_control_retired_after_mesh\\\": false,\\n" +\n                    "  \\\"industrial_validation\\\": false,\\n" +\n                    "  \\\"ansys_equivalence\\\": false\\n}", Encoding.UTF8);\n            }'''
if entry_anchor not in text:
    raise SystemExit('C8.82 request-evidence anchor not found; refusing non-deterministic patch')
text = text.replace(entry_anchor, entry_replacement, 1)

anchor = '''                meshedPartName = geometry.Parts.First().Key;\n                // Pinned native path: Controller.CreateMesh -> CreateMeshFromBrep -> NetGenMesher -> ImportGeneratedMesh.\n                createMeshReturned = _controller.CreateMesh(meshedPartName);'''
replacement = '''                meshedPartName = geometry.Parts.First().Key;\n                string c882MeshingParametersName = null;\n\n                // C8.82: explicit native NetGen mesh-size contract for sensitivity studies.\n                // Mirror the GUI selection contract and inventory the canonicalized object returned by\n                // Controller before relying on the stronger downstream proof: actual mesh refinement.\n                if (!String.IsNullOrWhiteSpace(c882CfgPath) && String.IsNullOrWhiteSpace(c882MaxHText))\n                    throw new InvalidOperationException("C8.82 mesh-size evidence was requested but ASTERMAX_STEP_MESH_MAXH_MM was not inherited by AsterMax.");\n                if (!String.IsNullOrWhiteSpace(c882MaxHText))\n                {\n                    double requestedMaxH;\n                    if (!Double.TryParse(c882MaxHText, NumberStyles.Float, CultureInfo.InvariantCulture, out requestedMaxH) ||\n                        !Finite(requestedMaxH) || requestedMaxH <= 0)\n                        throw new InvalidOperationException("ASTERMAX_STEP_MESH_MAXH_MM must be a finite value > 0 mm.");\n\n                    int targetPartId = geometry.Parts[meshedPartName].PartId;\n                    c882MeshingParametersName = "C8_82_MaxH_" + requestedMaxH.ToString("0.###", CultureInfo.InvariantCulture);\n                    MeshingParameters p = new MeshingParameters(c882MeshingParametersName);\n                    p.RelativeSize = false;\n                    p.MaxH = requestedMaxH;\n                    p.MinH = 0;\n                    p.SecondOrder = true;\n                    p.CreationIds = new int[] { targetPartId };\n                    CaeGlobals.Selection geometrySelection = new CaeGlobals.Selection();\n                    geometrySelection.SelectItem = CaeGlobals.vtkSelectItem.Part;\n                    geometrySelection.Add(new CaeGlobals.SelectionNodeIds(CaeGlobals.vtkSelectOperation.Add, false, new int[] { targetPartId }, true));\n                    p.CreationData = geometrySelection;\n                    _controller.AddMeshingParametersCommand(p);\n\n                    MeshingParameters admitted = _controller.GetMeshingParameters(p.Name);\n                    bool admittedIsNull = admitted == null;\n                    bool idsNull = admitted == null || admitted.CreationIds == null;\n                    int idCount = idsNull ? 0 : admitted.CreationIds.Length;\n                    bool dataNull = admitted == null || admitted.CreationData == null;\n                    bool geometryBased = !dataNull && admitted.CreationData.IsGeometryBased();\n                    bool admittedRelativeSize = admitted != null && admitted.RelativeSize;\n                    double admittedMaxH = admitted == null ? Double.NaN : admitted.MaxH;\n                    bool maxHMatch = admitted != null && Finite(admittedMaxH) && Math.Abs(admittedMaxH - requestedMaxH) <= 1e-12;\n\n                    if (!String.IsNullOrWhiteSpace(c882CfgPath))\n                    {\n                        File.WriteAllText(c882CfgPath, "{\\n  \\\"schema\\\": \\\"astermax.c8.82.native-netgen-size.v8\\\",\\n" +\n                            "  \\\"request_environment_seen\\\": true,\\n" +\n                            "  \\\"requested_maxh_raw\\\": " + Json(c882MaxHText) + ",\\n" +\n                            "  \\\"requested_maxh_mm\\\": " + requestedMaxH.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                            "  \\\"target_geometry_part_id_before_command\\\": " + targetPartId.ToString(CultureInfo.InvariantCulture) + ",\\n" +\n                            "  \\\"admitted_is_null\\\": " + (admittedIsNull ? "true" : "false") + ",\\n" +\n                            "  \\\"admitted_creation_ids_null\\\": " + (idsNull ? "true" : "false") + ",\\n" +\n                            "  \\\"admitted_creation_id_count\\\": " + idCount.ToString(CultureInfo.InvariantCulture) + ",\\n" +\n                            "  \\\"admitted_creation_data_null\\\": " + (dataNull ? "true" : "false") + ",\\n" +\n                            "  \\\"admitted_creation_data_geometry_based\\\": " + (geometryBased ? "true" : "false") + ",\\n" +\n                            "  \\\"admitted_relative_size\\\": " + (admittedRelativeSize ? "true" : "false") + ",\\n" +\n                            "  \\\"admitted_maxh_mm\\\": " + (Finite(admittedMaxH) ? admittedMaxH.ToString("R", CultureInfo.InvariantCulture) : "null") + ",\\n" +\n                            "  \\\"maxh_match\\\": " + (maxHMatch ? "true" : "false") + ",\\n" +\n                            "  \\\"part_specific_parameters_admitted\\\": " + ((!admittedIsNull && maxHMatch) ? "true" : "false") + ",\\n" +\n                            "  \\\"native_create_mesh_started\\\": true,\\n" +\n                            "  \\\"meshing_control_retired_after_mesh\\\": true,\\n" +\n                            "  \\\"industrial_validation\\\": false,\\n" +\n                            "  \\\"ansys_equivalence\\\": false\\n}", Encoding.UTF8);\n                    }\n\n                    if (admittedIsNull || !maxHMatch || admittedRelativeSize)\n                        throw new InvalidOperationException("C8.82 canonical MeshingParameters admission failed; see NETGEN_CONFIG.json.");\n                }\n\n                // Pinned native path: Controller.CreateMesh -> CreateMeshFromBrep -> NetGenMesher -> ImportGeneratedMesh.\n                createMeshReturned = _controller.CreateMesh(meshedPartName);\n\n                // The size-control object is pre-processing state. Once the generated FE mesh is imported, the\n                // original geometry selection can become stale and poison the later structural validity gate.\n                // Retire only this C8.82 control after CreateMesh; the generated mesh remains the evidence.\n                if (!String.IsNullOrWhiteSpace(c882MeshingParametersName))\n                    _controller.RemoveMeshingParameters(new string[] { c882MeshingParametersName });'''
if anchor not in text:
    raise SystemExit('C8.82 mesh-size anchor not found; refusing non-deterministic patch')
text = text.replace(anchor, replacement, 1)
path.write_text(text, encoding='utf-8')
print(f'C8.82 native NetGen mesh-size lifecycle seam applied: {path}')
